@font-face{font-family:'Baylor Bears';      font-weight:400;}

:root{
  --bu-mark-white: url(<data-uri>);
  --bu-mark-green: url(<data-uri>);
  --bear-gold:     url(<data-uri>);
  --bear-green:    url(<data-uri>);
  --lockup-white:  url(<data-uri>);
}
